content.text:
{
  "name": "JUMO Quantrol温度控制器",
  "name_en": "JUMO Quantrol Temperature Controller",
  "manufacturer": "JUMO",
  "description": "用于实验室温度调节与监测的温度控制器，可读取当前温度、设定值、加热输出占空比和加热器开关状态，并支持任务准备、测量、停止和复位等控制操作。",
  "description_en": "A temperature controller for laboratory temperature regulation and monitoring. It can read the current temperature, setpoint, heater output duty cycle, and heater on/off state, and supports task preparation, measurement, stopping, and reset operations.",
  "actions": [
    {
      "action_name": "auto-attrs",
      "description": "返回该温度控制器可用属性的字典。",
      "description_en": "Return a dictionary of available attributes for the temperature controller."
    },
    {
      "action_name": "auto-set_attr",
      "description": "设置或定义该温度控制器的属性值。",
      "description_en": "Set or define an attribute value of the temperature controller."
    },
    {
      "action_name": "auto-capabilities",
      "description": "返回该温度控制器支持的功能与能力信息。",
      "description_en": "Return the supported functions and capabilities of the temperature controller."
    },
    {
      "action_name": "auto-do_measure",
      "description": "执行一次测量或状态采集，获取温度控制器的当前读数。",
      "description_en": "Perform a measurement or status acquisition to obtain current readings from the temperature controller."
    },
    {
      "action_name": "auto-prepare_task",
      "description": "为温度控制任务或实验步骤进行准备。",
      "description_en": "Prepare a temperature control task or experimental step."
    },
    {
      "action_name": "auto-stop_task",
      "description": "停止当前温度控制任务或相关操作。",
      "description_en": "Stop the current temperature control task or related operation."
    },
    {
      "action_name": "auto-reset",
      "description": "复位温度控制器。",
      "description_en": "Reset the temperature controller."
    }
  ],
  "tag_hints": [
    "temperature control",
    "process temperature monitoring",
    "setpoint control",
    "heater duty cycle",
    "heater on/off status",
    "PID temperature controller",
    "JUMO Quantrol"
  ]
}

